#pragma once
#include "Arduino.h"
#include "json.hpp"
namespace wave {inline nlohmann::json fixtures=nlohmann::json::array();}
class WiFiClientSecure{public:void setInsecure(){}};
class ResponseStream {public:std::string body;size_t pos=0;int read(){return pos<body.size()?(uint8_t)body[pos++]:-1;}size_t readBytes(char*b,size_t n){n=std::min(n,body.size()-pos);memcpy(b,body.data()+pos,n);pos+=n;return n;}size_t readBytes(uint8_t*b,size_t n){return readBytes((char*)b,n);}int available(){return body.size()-pos;}};
class HTTPClient{String url;ResponseStream stream;public:void setTimeout(unsigned){}bool begin(String u){url=u;return true;}bool begin(WiFiClientSecure&,String u){return begin(u);}void addHeader(String,String){}void end(){}int request(const char*method,const String&body=""){stream={};Serial.printf("FIXTURE HTTP %s %s\n",method,url.c_str());if(wave::network!="ONLINE")return -1;for(auto&f:wave::fixtures){if(url.find(f.value("match",std::string("__none__")))!=std::string::npos&&f.value("method",std::string("GET"))==method){stream.body=f.value("body",std::string());if(f.contains("hex")){auto h=f["hex"].get<std::string>();stream.body.clear();for(size_t i=0;i+1<h.size();i+=2)stream.body+=char(strtoul(h.substr(i,2).c_str(),nullptr,16));}Serial.printf("FIXTURE response %d (%zu bytes)\n",f.value("status",200),stream.body.size());return f.value("status",200);}}wave::log("UNSUPPORTED live Arduino HTTP: no matching test fixture");return -1;}int GET(){return request("GET");}int POST(const String&b){Serial.printf("FIXTURE request body: %s\n",b.c_str());return request("POST",b);}String getString(){return stream.body;}int getSize(){return stream.body.size();}ResponseStream&getStream(){return stream;}ResponseStream*getStreamPtr(){return &stream;}};
